5	Heatmap	Heatmap merupakan dasbor monitoring berbasis peta digital yang berfungsi untuk melacak, memetakan, dan mengelola tiket gangguan (Trouble Ticket) jaringan fiber optik secara real-time di berbagai wilayah operasional Indonesia. Sistem ini mengintegrasikan visualisasi sebaran lokasi gangguan pada peta interaktif dengan panel kontrol status operasional—seperti jumlah tiket yang belum ditangani (Not Yet Handled), sedang diproses (Progress), maupun yang sudah selesai (Done).	/img/heatmap/img_1793783187348.png	2026-10-23 03:57:10.046231+00	2026-11-13 02:49:09.497338+00	2
9	HRIS	HRIS (Human Resources Information System) adalah platform manajemen sumber daya manusia berbasis web terintegrasi yang dirancang khusus untuk mengotomatisasi dan menyederhanakan seluruh administrasi kepegawaian di PT Quantum Nusatama secara terpusat, mulai dari pengelolaan database karyawan, pencatatan absensi digital, hingga sistem pengajuan cuti dan justifikasi kehadiran secara real-time.	/img/hris/img_1793781911446.png	2026-10-26 10:14:03.572264+00	2026-11-13 02:49:09.497338+00	2
1	OSS WEB	OSS (Operation Support System) Web adalah aplikasi manajemen operasional berbasis website milik PT Quantum Nusatama yang dirancang untuk mendukung dan mengoptimalkan proses kerja inti perusahaan. Terintegrasi langsung dengan sistem HRIS, platform ini berfungsi sebagai pusat kendali (control center) untuk mencatat, mengelola, melacak, dan menyelesaikan berbagai permintaan pengerjaan (Work Order) dari client secara terstruktur dan real-time.	/img/oss_web/img_1792555546105.png	2026-10-20 09:48:31.387545+00	2026-11-13 02:49:09.497338+00	2
16	HRIS XL	XLSMART HRIS adalah portal layanan mandiri karyawan untuk mengelola administrasi kepegawaian di PT XLSMART Telecom Sejahtera Tbk secara terpusat. Gunakan panduan ini sebagai referensi langkah demi langkah untuk memperbarui profil karyawan, melakukan presensi digital, serta memproses pengajuan cuti dan justifikasi kehadiran secara real-time.	/img/hris_xl/img_1795413508738.webp	2026-11-13 07:11:16.498233+00	2026-11-23 05:58:29.143036+00	5
2	OSS Mobile	OSS Mobile adalah aplikasi pendukung operasional berbasis smartphone milik PT Quantum Nusatama yang memfasilitasi kebutuhan kerja harian dan pengerjaan lapangan para teknisi secara terintegrasi. Aplikasi ini memuat fitur manajemen kehadiran (absensi shift), pengajuan formulir SDM, pengunduhan e-slip gaji, hingga eksekusi Work Order (IKR, Backbone, Project) secara real-time dengan dukungan upload foto geotagging/timestamp serta pencatatan koordinat lokasi. Selain itu, OSS Mobile juga menyederhanakan pengelolaan material lapangan melalui pencatatan penggunaan barang, konfirmasi penerimaan/retur, serta fitur pemindaian QR Code untuk transfer material antarteknisi secara praktis.	/img/oss_mobile/img_1792565970299.jpg	2026-10-20 09:48:31.387545+00	2026-11-13 07:09:36.928027+00	3
15	HRIS Lautantelco	HRIS (Human Resources Information System) adalah platform manajemen sumber daya manusia berbasis web terintegrasi yang dirancang khusus untuk mengotomatisasi dan menyederhanakan seluruh administrasi kepegawaian di Lautantelco secara terpusat, mulai dari pengelolaan database karyawan, pencatatan absensi digital, hingga sistem pengajuan cuti dan justifikasi kehadiran secara real-time.	/img/hris_lautantelco/img_1795413751691.webp	2026-11-13 07:10:51.575715+00	2026-11-23 06:03:22.860912+00	5
14	Backbone Mobile		/img/backbone_mobile/img_1795414042096.webp	2026-11-13 07:09:18.430695+00	2026-11-23 06:07:22.599351+00	3
12	Email	Email kantor adalah layanan surat elektronik resmi berbasis domain perusahaan yang disediakan bagi seluruh karyawan sebagai sarana komunikasi internal maupun eksternal yang profesional. Melalui akun email ini, pengguna dapat mengirim dan menerima pesan resmi, berbagi dokumen kerja, serta mengakses berbagai layanan kolaborasi terintegrasi seperti kalender jadwal rapat dan penyimpanan awan perusahaan. Untuk menjaga keamanan data dan kelancaran operasional, setiap pengguna diharapkan menggunakan akun email kantor sesuai dengan kebijakan teknologi informasi perusahaan yang berlaku serta rutin memperbarui kata sandi secara berkala.	/img/email/img_1795413488752.webp	2026-11-04 10:01:46.816481+00	2026-11-23 05:58:08.821652+00	1
4	PM Tracker	PM Tracker (Preventive Maintenance Tracker) Umum di PT. Quantum Nusatama adalah modul aplikasi internal berbasis web pada portal perusahaan yang dirancang untuk memantau, mencatat, dan mengelola aktivitas perawatan preventif rutin pada infrastruktur jaringan telekomunikasi. Aplikasi ini berfungsi memastikan kesiapan dan keandalan perangkat maupun jalur jaringan sesuai standar operasional perusahaan, sekaligus memudahkan tim lapangan dan manajemen dalam melacak progres pekerjaan, jadwal pemeliharaan berkala, serta pelaporan kondisi aset di luar cakupan modul khusus klien tertentu.	/img/pm_tracker/img_1795588727725.webp	2026-10-23 03:57:01.804501+00	2026-11-27 09:14:47.517477+00	2
6	Mapping	Modul Mapping pada portal internal PT. Quantum Nusatama adalah aplikasi berbasis web yang berfungsi untuk memetakan lokasi aset jaringan telekomunikasi sekaligus mengatur pembagian wilayah kerja dan penjadwalan teknisi lapangan secara terpusat. Melalui sistem pemetaan geografis ini, tim operasional dan manajemen dapat memvisualisasikan titik koordinat perangkat maupun jalur jaringan, mengoptimalkan distribusi tugas harian berdasarkan kedekatan area, serta mempercepat koordinasi dan respons tim di lapangan dalam kegiatan pemeliharaan maupun penanganan gangguan.	/img/mapping/img_1795588790994.webp	2026-10-23 03:57:21.450651+00	2026-11-27 09:15:56.594926+00	2
